import 'package:cerne/core/network/error_mapper.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:cerne/core/storage/secure_token_storage.dart';
import 'package:dio/dio.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:fpdart/fpdart.dart';

/// Which bearer value a call carries: the anon key (no user session exists
/// yet or is being replaced) or the stored access token (an existing
/// session's authenticated calls).
enum AuthMode { anonKey, userSession }

/// The single way any feature calls the backend (FR-003, contracts/http-client.md).
/// Every `data/` layer depends on this, never on `dio` directly. Never throws
/// past this boundary — every dio exception is caught and mapped to a
/// [Failure] (FR-003 "never an unhandled crash").
class ApiClient {
  ApiClient({
    required this._dio,
    required this._tokenStorage,
    required this._anonKey,
  });

  final Dio _dio;
  final SecureTokenStorage _tokenStorage;
  final String _anonKey;

  Future<Either<Failure, Map<String, dynamic>>> call(
    String function, {
    required String method,
    Map<String, dynamic>? body,
    List<String>? pathSegments,
    Map<String, dynamic>? queryParameters,
    AuthMode authMode = AuthMode.userSession,
    // When false, returns the full decoded body (`{"data": ..., "meta":
    // ...}`) verbatim instead of unwrapping/validating the inner "data"
    // object. Needed by `entries-list`, whose "data" is an array (not an
    // object) and whose "meta.nextCursor" every other call site has no use
    // for and would otherwise be discarded. Every pre-existing call site
    // omits this and is byte-for-byte unaffected.
    bool unwrapData = true,
  }) async {
    final baseUrl = dotenv.env['FUNCTIONS_BASE_URL'] ?? '';
    final segments = [function, ...?pathSegments];
    final url = '$baseUrl/${segments.join('/')}';

    final bearer = authMode == AuthMode.anonKey
        ? _anonKey
        : (await _tokenStorage.readAccessToken() ?? '');

    try {
      final response = await _dio.request<Map<String, dynamic>>(
        url,
        data: body,
        queryParameters: queryParameters,
        options: Options(
          method: method,
          headers: {'apikey': _anonKey, 'Authorization': 'Bearer $bearer'},
        ),
      );
      if (!unwrapData) {
        return Right(response.data ?? const {});
      }
      final rawData = response.data?['data'];
      if (rawData != null && rawData is! Map<String, dynamic>) {
        return Left(
          ValidationFailure(
            message: 'Malformed response: "data" is not an object',
            requestId: '',
          ),
        );
      }
      return Right(rawData as Map<String, dynamic>? ?? const {});
    } on DioException catch (e) {
      return Left(_mapException(e));
    }
  }

  Failure _mapException(DioException e) {
    const timeoutTypes = {
      DioExceptionType.connectionTimeout,
      DioExceptionType.sendTimeout,
      DioExceptionType.receiveTimeout,
    };

    // `e.message` is Dio's own internal exception text (e.g. "Failed host
    // lookup") — never shown to the user; both client-synthesized failures
    // below carry a fixed, user-facing message instead, same as every
    // backend-mapped `Failure` already does via `ErrorMapper`.
    if (timeoutTypes.contains(e.type)) {
      return const NetworkTimeoutFailure(
        message: 'A conexão demorou demais. Tente novamente.',
        requestId: '',
      );
    }

    final responseData = e.response?.data;
    if (responseData is Map<String, dynamic>) {
      return ErrorMapper.fromResponse(responseData);
    }

    // No response at all (connection error) — NETWORK_OFFLINE never arrives
    // as an HTTP response, so it is synthesized client-side here.
    return const NetworkOfflineFailure(
      message: 'Sem conexão com a internet.',
      requestId: '',
    );
  }
}

import 'dart:convert';

import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

/// On-device, cross-restart persistence for the entries the user has
/// already seen (the PRD's "local read cache" — requirements.md line 50/125:
/// results from it stay visible offline and reconcile with the server on
/// reconnect, with no duplicates). Keychain-backed, same pattern as
/// `VaultSecureStorage` — journal content is personal data, so it stays
/// encrypted at rest like the PIN it already sits behind.
///
/// Distinct from `EntriesRepositoryImpl`'s in-memory `cachedEntries`: that
/// field only ever held optimistic just-created entries for this process's
/// lifetime (research.md R8, 003-multimodal-capture). This class is what
/// makes that same list survive an app restart, which is what a cold open
/// on an already-offline device needs (closing snapshot at unit completion
/// did not cover this path — see Meus Registros intervention report).
class EntriesLocalCache {
  EntriesLocalCache({FlutterSecureStorage? storage})
    : _storage = storage ?? const FlutterSecureStorage();

  final FlutterSecureStorage _storage;

  static const _key = 'entriesLocalCache';

  Future<List<Entry>> readAll() async {
    final raw = await _storage.read(key: _key);
    if (raw == null) return const [];
    try {
      final decoded = jsonDecode(raw) as List<dynamic>;
      return decoded.map((e) => _fromJson(e as Map<String, dynamic>)).toList();
    } on FormatException {
      return const [];
    } on TypeError {
      return const [];
    }
  }

  Future<void> writeAll(List<Entry> entries) {
    final encoded = jsonEncode(entries.map(_toJson).toList());
    return _storage.write(key: _key, value: encoded);
  }

  Map<String, dynamic> _toJson(Entry e) => {
    'id': e.id,
    'content': e.content,
    'source': e.source.name,
    'chatMessageId': e.chatMessageId,
    'occurredAt': e.occurredAt.toUtc().toIso8601String(),
    'tags': [
      for (final tag in e.tags) {'id': tag.id, 'name': tag.name},
    ],
    'piiStatus': e.piiStatus.name,
    'piiSpans': [
      for (final span in e.piiSpans)
        {'start': span.start, 'end': span.end, 'type': span.type},
    ],
    'embeddingStatus': e.embeddingStatus.name,
    'mediaDurationSeconds': e.mediaDurationSeconds,
    'serverRevision': e.serverRevision,
    'createdAt': e.createdAt.toUtc().toIso8601String(),
    'updatedAt': e.updatedAt.toUtc().toIso8601String(),
    'similarity': e.similarity,
  };

  Entry _fromJson(Map<String, dynamic> data) => Entry(
    id: data['id'] as String,
    content: data['content'] as String,
    source: EntrySource.values.byName(data['source'] as String),
    chatMessageId: data['chatMessageId'] as String?,
    occurredAt: DateTime.parse(data['occurredAt'] as String),
    tags: (data['tags'] as List<dynamic>)
        .map(
          (t) => EntryTag(
            id: (t as Map<String, dynamic>)['id'] as String,
            name: t['name'] as String,
          ),
        )
        .toList(),
    piiStatus: PiiStatus.values.byName(data['piiStatus'] as String),
    piiSpans: (data['piiSpans'] as List<dynamic>)
        .map(
          (s) => PiiSpan(
            start: (s as Map<String, dynamic>)['start'] as int,
            end: s['end'] as int,
            type: s['type'] as String,
          ),
        )
        .toList(),
    embeddingStatus: EmbeddingStatus.values.byName(
      data['embeddingStatus'] as String,
    ),
    mediaDurationSeconds: data['mediaDurationSeconds'] as int?,
    serverRevision: data['serverRevision'] as int,
    createdAt: DateTime.parse(data['createdAt'] as String),
    updatedAt: DateTime.parse(data['updatedAt'] as String),
    similarity: (data['similarity'] as num?)?.toDouble(),
  );
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/features/capture/presentation/widgets/open_insertion_modal.dart';
import 'package:cerne/features/home/presentation/widgets/app_drawer.dart';
import 'package:flutter/material.dart';

/// Fixed dark-green header (☰ + "Cerne" wordmark) and an empty conversation
/// area, plus a composer bar that is rendered but fully disabled — no fake
/// messages, no RF04 wiring (FR-016; research.md R10). Scaffold's `drawer`
/// gives the ☰ icon its tap target for free (User Story 4).
class HomeChatShellPage extends StatelessWidget {
  const HomeChatShellPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      drawer: const AppDrawer(),
      appBar: AppBar(
        backgroundColor: DesignTokens.colorPrimary,
        foregroundColor: DesignTokens.colorOnPrimary,
        title: Text(
          'Cerne',
          style: DesignTokens.textTitleLg.copyWith(
            color: DesignTokens.colorOnPrimary,
          ),
        ),
      ),
      body: Column(
        children: [
          const Expanded(child: SizedBox.expand()),
          _ComposerBar(),
        ],
      ),
    );
  }
}

class _ComposerBar extends StatelessWidget {
  const _ComposerBar();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        border: Border(top: BorderSide(color: DesignTokens.colorBorder)),
      ),
      child: Row(
        children: [
          IconButton(
            onPressed: () => openInsertionModal(context),
            icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
          ),
          Expanded(
            child: TextField(
              enabled: false,
              decoration: const InputDecoration(
                hintText: 'Escreva uma mensagem...',
              ),
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          IconButton(
            onPressed: null,
            icon: const Icon(Icons.send, color: DesignTokens.colorTextSecondary),
          ),
        ],
      ),
    );
  }
}

