  bool get retryable => false;

  @override
  String get code => 'PAYLOAD_TOO_LARGE';
}

class OcrNoTextFailure extends Failure {
  const OcrNoTextFailure({required super.message, required super.requestId});

  @override
  bool get retryable => false;

  @override
  String get code => 'OCR_NO_TEXT';
}
